namespace ghidra.app.plugin.core.datamgr.tree;





using docking.widgets.tree;
using ghidra.app.plugin.core.datamgr.util;
using ghidra.program.model.data;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.exception;

public class CategoryNode : DataTypeTreeNode {

	private Category category;
	private string name;

	private bool isCut;
	private DtFilterState filterState;

	protected CategoryNode(Category category, DtFilterState filterState) {
		this.filterState = filterState;
		setCategory(category);
	}

	protected void setCategory(Category category) {
		this.category = category;
		if (category != null) {
			this.name = category.getName();
		}
	}

	/* @Override */
	protected List<GTreeNode> generateChildren() {
		if (category == null) {
			return Collections.emptyList();
		}

		Category[] subCategories = category.getCategories();
		DataType[] dataTypes = category.getDataTypes();
		List<GTreeNode> list = new(subCategories.length + dataTypes.length);
		foreach (Category subCategory in subCategories) {
			list.add(new CategoryNode(subCategory, filterState));
		}

		foreach (DataType dataType in dataTypes) {
			if (passesFilters(dataType)) {
				list.add(new DataTypeNode(dataType));
			}
		}

		Collections.sort(list);

		return list;
	}

	private bool passesFilters(DataType dataType) {
		return filterState.passesFilters(dataType);
	}

	/* @Override */
	public int compareTo(GTreeNode node) {
		if (node is CategoryNode) {
			return base.compareTo(node);
		}

		return -1; // CategoryNodes are always come before ****everything else****
	}

	/* @Override */
	public int hashCode() {
		return name.hashCode();
	}

	/* @Override */
	public bool equals(object o) {
		if (this == o) {
			return true;
		}
		if (getClass() != o.GetType()) {
			return false;
		}

		CategoryNode otherNode = (CategoryNode) o;
		CategoryPath otherPath = otherNode.getCategory().getCategoryPath();
		CategoryPath path = getCategory().getCategoryPath();
		if (!path.equals(otherPath)) {
			return false;
		}
		return name.equals(otherNode.name);
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		// always show leaf nodes as closed in addition to collapsed non-leaf nodes
		if (!expanded) {
			return DataTypeUtils.getClosedFolderIcon(isCut);
		}

		// expanded node with data
		return DataTypeUtils.getOpenFolderIcon(isCut);
	}

	/* @Override */
	public string getName() {
		return name;
	}

	/* @Override */
	public string getToolTip() {
		return "<html>" + HTMLUtilities.escapeHTML(category.getCategoryPathName());
	}

	/* @Override */
	public bool isLeaf() {
		return false;
	}

	public bool canRename() {
		return isModifiable();
	}

	public Category getCategory() {
		return category;
	}

	public DataTypeNode getNode(DataType dataType) {
		// call this method to make sure children are loaded
		List<GTreeNode> children = getChildren();
		foreach (GTreeNode node in children) {
			if ((node is DataTypeNode)) {
				DataTypeNode dataTypeNode = (DataTypeNode) node;
				if (dataTypeNode.getDataType() == dataType) {
					return dataTypeNode;
				}
			}
		}
		return null;
	}

	public void categoryAdded(Category newCategory) {

		if (!isLoaded()) {
			return;
		}

		CategoryNode node = new CategoryNode(newCategory, filterState);
		List<GTreeNode> children = getChildren();
		int index = Collections.binarySearch(children, node);
		if (index >= 0) {
			// if a node with that name exists, then we don't need to add one for the new category
			if (node.getName().equals(children.get(index).getName())) {
				return;
			}
		}
		if (index < 0) {
			index = -index - 1;
		}
		addNode(index, node);
	}

	public void dataTypeAdded(DataType dataType) {
		if (!isLoaded()) {
			return;
		}

		DataTypeArchiveGTree tree = (DataTypeArchiveGTree) getTree();

		if (tree == null) {
			return;
		}

		if (!passesFilters(dataType)) {
			return;
		}

		DataTypeNode node = new DataTypeNode(dataType);
		List<GTreeNode> allChildrenList = getChildren();
		int index = Collections.binarySearch(allChildrenList, node);
		if (index >= 0) {
			if (node.getName().equals(allChildrenList.get(index).getName())) {
				return;
			}
		}
		if (index < 0) {
			index = -index - 1;
		}
		addNode(index, node); // only add it if is not already there
	}

	public void categoryRemoved(string categoryName) {
		if (!isLoaded()) {
			return;
		}
		foreach (GTreeNode node in getChildren()) {
			if ((node is CategoryNode) && node.getName().equals(categoryName)) {
				removeNode(node);
				return;
			}
		}
	}

	public void dataTypeRemoved(string dataTypeName) {
		if (!isLoaded()) {
			return;
		}

		foreach (GTreeNode node in getChildren()) {
			if ((node is DataTypeNode) && node.getName().equals(dataTypeName)) {
				removeNode(node);
				return;
			}
		}
	}

	public void dataTypeChanged(DataType dataType) {
		if (!isLoaded()) {
			return;
		}

		string dataTypeName = dataType.getName();
		foreach (GTreeNode node in getChildren()) {
			if ((node is DataTypeNode) && node.getName().equals(dataTypeName)) {
				((DataTypeNode) node).dataTypeChanged();
				return;
			}
		}
	}

	/* @Override */
	public void valueChanged(object newValue) {
		string newName = newValue.toString();
		int transactionID =
			category.getDataTypeManager().startTransaction("Rename Category " + newName);
		try {
			category.setName(newName);
		}
		catch (DuplicateNameException e) {
			Msg.showError(getClass(), null, "Rename Failed",
				"Category by the name " + newName + " already exists in this category.");
		}
		catch (InvalidNameException exc) {
			string msg = exc.getMessage();
			if (msg == null) {
				msg = "Invalid name specified: " + newName;
			}
			Msg.showError(getClass(), null, "Invalid name specified", exc.getMessage());
		}
		finally {
			category.getDataTypeManager().endTransaction(transactionID, true);
		}
	}

	/* @Override */
	public bool isEditable() {
		return isModifiable();
	}

	/* @Override */
	public string toString() {
		return getName();
	}

	/**
	 * Signals to this node that it has been cut during a cut operation, for example, like during a
	 * cut/paste operation.
	 * <p>
	 * This implementation will throw a runtime exception if this method is called and
	 * {@link #canCut()} returns false.
	 * 
	 * @param isCut true signals that the node has been cut; false that it is not cut.
	 */
	/* @Override */
	public void setNodeCut(bool isCut) {
		if (!canCut()) {
			throw new AssertException("Cannot call isCut() on a node that cannot be cut.");
		}
		this.isCut = isCut;
		fireNodeChanged();
	}

	/* @Override */
	public bool canCut() {
		return isModifiable();
	}

	/* @Override */
	public bool canPaste(List<GTreeNode> pastedNodes) {
		return isModifiable();
	}

	/* @Override */
	public bool isCut() {
		return isCut;
	}

	/* @Override */
	public DataTypeStoreNode getArchiveNode() {
		GTreeNode parent = getParent();
		if (parent == null) {
			return null; // could happen during tree mutations
		}

		return ((DataTypeTreeNode) parent).getArchiveNode();
	}

	/* @Override */
	public bool isModifiable() {
		DataTypeStoreNode archiveNode = getArchiveNode();
		if (archiveNode == null) {
			return false;
		}
		return getArchiveNode().isModifiable();
	}

	/**
	 * This method is handy to signal whether this node is can be used to perform actions. Returning
	 * false from this method is essentially a way to disable the actions that can be performed upon
	 * this node.
	 *
	 * @return true if this node is enabled.
	 */
	public bool isEnabled() {
		return true;
	}

	/* @Override */
	public bool canDelete() {
		return true;
	}
}
